  ('codex_cost_events_v1_mv', 'MaterializedView', '', '', '', '', 'SELECT Timestamp, toJSONString((mapSort(ResourceAttributes), mapSort(LogAttributes))) AS Identity, coalesce(nullIf(ResourceAttributes[\'user.email\'], \'\'), nullIf(ResourceAttributes[\'enduser.id\'], \'\'), \'\') AS UserEmail, LogAttributes[\'conversation.id\'] AS ConversationId, LogAttributes[\'model\'] AS Model, multiIf(match(LogAttributes[\'model\'], \'^(us|us-gov|eu|apac|jp|au|in|global)\\\\.\'), \'bedrock-runtime\', match(LogAttributes[\'model\'], \'^[a-z][a-z0-9-]*[a-z]\\\\.\'), \'bedrock-mantle\', (ResourceAttributes[\'backend\']) IN (\'bedrock-mantle\', \'bedrock-runtime\'), ResourceAttributes[\'backend\'], \'unknown\') AS Backend, ResourceAttributes[\'project.name\'] AS ProjectName, EventName, multiIf((EventName IN (\'codex.sse_event\', \'codex.websocket_event\')) AND ((LogAttributes[\'event.kind\']) = \'response.completed\') AND hasAny(mapKeys(LogAttributes), [\'input_token_count\', \'cached_token_count\', \'cache_write_token_count\', \'output_token_count\', \'reasoning_token_count\']), \'usage\', (EventName IN (\'codex.sse_event\', \'codex.websocket_event\')) AND ((LogAttributes[\'event.kind\']) = \'response.completed\'), \'completion\', (EventName IN (\'codex.sse_event\', \'codex.websocket_event\')) AND ((LogAttributes[\'event.kind\']) = \'response.failed\'), \'stream_error\', EventName IN (\'codex.sse_event\', \'codex.websocket_event\'), \'scope_evidence\', EventName IN (\'codex.api_request\', \'codex.api_error\'), \'request\', EventName = \'codex.tool_result\', \'tool\', EventName = \'codex.tool_decision\', \'approval\', EventName = \'codex.turn_ttft\', \'ttft\', (NOT has([\'codex.conversation_starts\', \'codex.startup_phase\', \'codex.user_prompt\'], EventName)) OR hasAny(mapKeys(LogAttributes), [\'input_token_count\', \'output_token_count\', \'cached_token_count\', \'cache_write_token_count\', \'reasoning_token_count\', \'tool_token_count\']), \'scope_evidence\', \'\') AS Kind, toUIn