  ('codex_cost_scope_v1_mv', 'MaterializedView', '', '', '', '', 'SELECT toStartOfMinute(Timestamp) AS Minute, coalesce(nullIf(ResourceAttributes[\'user.email\'], \'\'), nullIf(ResourceAttributes[\'enduser.id\'], \'\'), \'\') AS UserEmail, LogAttributes[\'conversation.id\'] AS ConversationId, LogAttributes[\'model\'] AS Model, multiIf(match(LogAttributes[\'model\'], \'^(us|us-gov|eu|apac|jp|au|in|global)\\\\.\'), \'bedrock-runtime\', match(LogAttributes[\'model\'], \'^[a-z][a-z0-9-]*[a-z]\\\\.\'), \'bedrock-mantle\', (ResourceAttributes[\'backend\']) IN (\'bedrock-mantle\', \'bedrock-runtime\'), ResourceAttributes[\'backend\'], \'unknown\') AS Backend, ResourceAttributes[\'project.name\'] AS ProjectName, EventName, groupUniqArrayState(toUInt8(toSecond(Timestamp))) AS Seconds FROM claude_code.otel_logs WHERE startsWith(EventName, \'codex.\') AND 1 AND (multiIf((EventName IN (\'codex.sse_event\', \'codex.websocket_event\')) AND ((LogAttributes[\'event.kind\']) = \'response.completed\') AND hasAny(mapKeys(LogAttributes), [\'input_token_count\', \'cached_token_count\', \'cache_write_token_count\', \'output_token_count\', \'reasoning_token_count\']), \'usage\', (EventName IN (\'codex.sse_event\', \'codex.websocket_event\')) AND ((LogAttributes[\'event.kind\']) = \'response.completed\'), \'completion\', (EventName IN (\'codex.sse_event\', \'codex.websocket_event\')) AND ((LogAttributes[\'event.kind\']) = \'response.failed\'), \'stream_error\', EventName IN (\'codex.sse_event\', \'codex.websocket_event\'), \'scope_evidence\', EventName IN (\'codex.api_request\', \'codex.api_error\'), \'request\', EventName = \'codex.tool_result\', \'tool\', EventName = \'codex.tool_decision\', \'approval\', EventName = \'codex.turn_ttft\', \'ttft\', (NOT has([\'codex.conversation_starts\', \'codex.startup_phase\', \'codex.user_prompt\'], EventName)) OR hasAny(mapKeys(LogAttributes), [\'input_token_count\', \'output_token_count\', \'cached_token_count\', \'cache_write_token_count\', \'reasoning_token_count\', \'tool_token_count\']), \'scope_evidence\', \'\') = \'scope_evidence\') GROUP BY Minute, UserEmail, ConversationId, Model, Backend, ProjectName, EventName'),
  ('codex_diagnostic_events_v1', 'ReplicatedAggregatingMergeTree', 'toYYYYMM(Second)', 'UserEmail, Second, Model, ConversationId, Backend, ProjectName, AttributesJSON', 'UserEmail, Second, Model, ConversationId, Backend, ProjectName, AttributesJSON', 'toDateTime(Second) + toIntervalDay(45) TO VOLUME \'cold\', toDateTime(Second) + toIntervalDay(90)', ''),
  ('codex_diagnostic_events_v1_mv', 'MaterializedView', '', '', '', '', 'WITH mapSort(ResourceAttributes) AS r, mapSort(LogAttributes) AS a SELECT coalesce(nullIf(r[\'user.email\'], \'\'), nullIf(r[\'enduser.id\'], \'\'), \'\') AS UserEmail, toStartOfSecond(Timestamp) AS Second, a[\'model\'] AS Model, a[\'conversation.id\'] AS ConversationId, multiIf(match(a[\'model\'], \'^(us|us-gov|eu|apac|jp|au|in|global)\\\\.\'), \'bedrock-runtime\', match(a[\'model\'], \'^[a-z][a-z0-9-]*[a-z]\\\\.\'), \'bedrock-mantle\', (r[\'backend\']) IN (\'bedrock-mantle\', \'bedrock-runtime\'), r[\'backend\'], \'unknown\') AS Backend, r[\'project.name\'] AS ProjectName, toJSONString(mapApply((k, v) -> (k, multiIf(has([\'input_token_count\', \'output_token_count\', \'cached_token_count\', \'cache_write_token_count\', \'reasoning_token_count\', \'tool_token_count\'], k), \'present\', k IN (\'error\', \'error.message\'), if(v = \'\', \'\', \'present\'), v)), mapFilter((k, v) -> has([\'event.name\', \'event.kind\', \'duration_ms\', \'attempt\', \'http.response.status_code\', \'error\', \'error.message\', \'success\', \'tool_name\', \'decision\', \'source\', \'startup.phase\', \'input_token_count\', \'output_token_count\', \'cached_token_count\', \'cache_write_token_count\', \'reasoning_token_count\', \'tool_token_count\'], k), a))) AS AttributesJSON, min(Timestamp) AS MinTimestamp, max(Timestamp) AS MaxTimestamp, uniqExactState((toString(toTimeZone(Timestamp, \'UTC\')), r, a)) AS Identities FROM claude_code.otel_logs WHERE startsWith(EventName, \'codex.\') AND startsWith(a[\'event.name\'], \'codex.\') AND 1 GROUP BY UserEmail, Second, Model, ConversationId, Backend, ProjectName, AttributesJSON'),
